function starPoints(cx, cy, outer, points){
  var pts = []; var step = Math.PI / points;
  for (var i = 0; i < points * 2; i++){
    var r = (i % 2 === 0) ? outer : outer / 2;
    var a = i * step - Math.PI / 2;
    pts.push([Math.round(cx + Math.cos(a) * r), Math.round(cy + Math.sin(a) * r)]);
  }
  return pts;
}
function polyPath(pts){
  var s = "M" + pts[0][0] + " " + pts[0][1];
  for (var i = 1; i < pts.length; i++) s += "L" + pts[i][0] + " " + pts[i][1];
  return s + "Z";
}
var EXPORTS = { starPoints: starPoints, polyPath: polyPath };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.StickerForgePure = EXPORTS; }
